JVM的新特性使用Metaspace（JEP 122）代替持久代（PermGen space）。在JVM参数方面，使用-XX:MetaSpaceSize和-XX:MaxMetaspaceSize代替原来的-XX:PermSize和-XX:MaxPermSize。
常用举例List对象多条件排序一个List 先按照名字的拼音排序，然后按照年龄排序
public static void main(String[] args) &#123;                List&lt;Person&gt; persons = getPersons();                long start = System.currentTimeMillis();        // 方法一：方法引用方式//        List&lt;Person&gt; result = persons.stream().sorted(Comparator.comparing(Person::getNamePinyin).thenComparing(Person::getAge)).collect(Collectors.toList());        List&lt;Person&gt; result = persons.stream()                .sorted(Comparator.comparing((Person p) -&gt; p.getNamePinyin())                        .thenComparing((Person p) -&gt; p.getAge()).collect(Collectors.toList());        long end = System.currentTimeMillis();        System.out.println(&quot;duration time:&quot; + (end-start) + &quot;ms&quot;);        for(Person p: result) &#123;            System.out.println(p);        &#125;    &#125;        public static List&lt;Person&gt; getPersons() &#123;        List&lt;Person&gt; persons = new ArrayList&lt;&gt;();        persons.add(new Person(&quot;中国&quot;, 24));        persons.add(new Person(&quot;中国&quot;, 23));        persons.add(new Person(&quot;中国&quot;, 78));        persons.add(new Person(&quot;美国&quot;, 23));        persons.add(new Person(&quot;泰国&quot;, 23));        persons.add(new Person(&quot;韩国&quot;, 23));        persons.add(new Person(&quot;日本&quot;, 23));        return persons;    &#125;

