配置使用配置类配置，可以参考如下所示：先创建一个builder，用于初始化ES clientpublic class EsClientBuilder &#123;    private int connectTimeoutMillis = 1000;    private int socketTimeoutMillis = 30000;    private int connectionRequestTimeoutMillis = 500;    private int maxConnectPerRoute = 10;    private int maxConnectTotal = 30;    private final List&lt;HttpHost&gt; httpHosts;    private EsClientBuilder(List&lt;HttpHost&gt; httpHosts) &#123;        this.httpHosts = httpHosts;    &#125;    public EsClientBuilder setConnectTimeoutMillis(int connectTimeoutMillis) &#123;        this.connectTimeoutMillis = connectTimeoutMillis;        return this;    &#125;    public EsClientBuilder setSocketTimeoutMillis(int socketTimeoutMillis) &#123;        this.socketTimeoutMillis = socketTimeoutMillis;        return this;    &#125;    public EsClientBuilder setConnectionRequestTimeoutMillis(int connectionRequestTimeoutMillis) &#123;        this.connectionRequestTimeoutMillis = connectionRequestTimeoutMillis;        return this;    &#125;    public EsClientBuilder setMaxConnectPerRoute(int maxConnectPerRoute) &#123;        this.maxConnectPerRoute = maxConnectPerRoute;        return this;    &#125;    public EsClientBuilder setMaxConnectTotal(int maxConnectTotal) &#123;        this.maxConnectTotal = maxConnectTotal;        return this;    &#125;    public static EsClientBuilder build(List&lt;HttpHost&gt; httpHosts) &#123;        return new EsClientBuilder(httpHosts);    &#125;    public RestHighLevelClient create() &#123;        HttpHost[] httpHostArr = httpHosts.toArray(new HttpHost[0]);        RestClientBuilder builder = RestClient.builder(httpHostArr);        builder.setRequestConfigCallback(requestConfigBuilder -&gt; &#123;            requestConfigBuilder.setConnectTimeout(connectTimeoutMillis);            requestConfigBuilder.setSocketTimeout(socketTimeoutMillis);            requestConfigBuilder.setConnectionRequestTimeout(connectionRequestTimeoutMillis);            return requestConfigBuilder;        &#125;);        builder.setHttpClientConfigCallback(httpClientBuilder -&gt; &#123;            httpClientBuilder.setMaxConnTotal(maxConnectTotal);            httpClientBuilder.setMaxConnPerRoute(maxConnectPerRoute);            return httpClientBuilder;        &#125;);        return new RestHighLevelClient(builder);    &#125;&#125;
再交给spring容器管理：@Configurationpublic class ESConfig &#123;    @Value(&quot;$&#123;elasticsearch.nodes&#125;&quot;)    private List&lt;String&gt; nodes;    @Value(&quot;$&#123;elasticsearch.schema&#125;&quot;)    private String schema;    @Value(&quot;$&#123;elasticsearch.max-connect-total&#125;&quot;)    private Integer maxConnectTotal;    @Value(&quot;$&#123;elasticsearch.max-connect-per-route&#125;&quot;)    private Integer maxConnectPerRoute;    @Value(&quot;$&#123;elasticsearch.connection-request-timeout-millis&#125;&quot;)    private Integer connectionRequestTimeoutMillis;    @Value(&quot;$&#123;elasticsearch.socket-timeout-millis&#125;&quot;)    private Integer socketTimeoutMillis;    @Value(&quot;$&#123;elasticsearch.connect-timeout-millis&#125;&quot;)    private Integer connectTimeoutMillis;    @Bean    public RestHighLevelClient getRestHighLevelClient() &#123;        List&lt;HttpHost&gt; httpHosts = new ArrayList&lt;&gt;();        for (String node : nodes) &#123;            try &#123;                String[] parts = StringUtils.split(node, &quot;:&quot;);                Assert.notNull(parts,&quot;Must defined&quot;);                Assert.state(parts.length == 2, &quot;Must be defined as &#x27;host:port&#x27;&quot;);                httpHosts.add(new HttpHost(parts[0], Integer.parseInt(parts[1]), schema));            &#125; catch (RuntimeException ex) &#123;                throw new IllegalStateException(                        &quot;Invalid ES nodes &quot; + &quot;property &#x27;&quot; + node + &quot;&#x27;&quot;, ex);            &#125;        &#125;        return EsClientBuilder.build(httpHosts)                .setConnectionRequestTimeoutMillis(connectionRequestTimeoutMillis)                .setConnectTimeoutMillis(connectTimeoutMillis)                .setSocketTimeoutMillis(socketTimeoutMillis)                .setMaxConnectTotal(maxConnectTotal)                .setMaxConnectPerRoute(maxConnectPerRoute)                .create();    &#125;&#125;
