环境准备install axioscnpm install axios --save&lt;script&gt;import axios from &#x27;axios&#x27;;export default &#123;    data() &#123;        return &#123;            ...        &#125;    &#125;,    methods:&#123;        ...    &#125;&#125;&lt;/script&gt;
前端代码执行的方法
downLoadMix() &#123;    let params = &#123;&#125;;  let url = this.$store.state.urlPrefix+&quot;/company/download&quot;;  let title = null;    axios(&#123;      method: &#x27;post&#x27;,     url,      headers: &#123;      &#x27;Content-Type&#x27;: &#x27;application/json&#x27;      &#125;,      data: params,      responseType: &#x27;arraybuffer&#x27;      &#125;).then(res =&gt; &#123;          let headers = res.headers;  //后端需要配置Access-Control-Expose-Headers,否则浏览器只能访问到默认的响应头,具体如下        let blob = new Blob([res.data], &#123;            type: headers[&#x27;content-type&#x27;]          &#125;);          let link = document.createElement(&#x27;a&#x27;);          link.href = window.URL.createObjectURL(blob);          if (!title) &#123;            const fileName = headers[&#x27;content-disposition&#x27;];            title = fileName.includes(&#x27;filename=&#x27;) ? fileName.split(&#x27;=&#x27;)[1] : &#x27;下载的表单文件&#x27;;          &#125;          link.download = title;          link.click();      &#125;);  &#125; 
后端代码(解决axios获取Http响应头)浏览器默认只能访问以下响应头

Cache-Control
Content-Language
Content-Type
Expires
Last-Modified
Pragma

因此如果想让浏览器能访问到其他响应头内容的话，比如Content-disposition,需要在服务器上设置 Access-Control-Expose-Headers
response.setHeader(&quot;Access-Control-Expose-Headers&quot;,&quot;Content-disposition&quot;);
或者完全放开
response.setHeader(&quot;Access-Control-Expose-Headers&quot;,&quot;*&quot;);
即可允许浏览器访问任意一个响应头，当然除次之外还要设置下载文件相关的响应头
response.setContentType(&quot;application/octet-stream&quot;);response.setHeader(&quot;Content-disposition&quot;, &quot;attachment;filename=createList.xls&quot;);//默认Excel名称
后端i/o流照常处理，例子如下：
@RequestMapping(value = &quot;/download&quot;, method = &#123;RequestMethod.POST&#125;, produces = &#123;&quot;application/json;charset=UTF-8&quot;&#125;)public void download(@RequestBody RequestFacade request, HttpServletResponse response) &#123;    try&#123;        //创建工作簿        XSSFWorkbook wb = new XSSFWorkbook();        //创建一个sheet        XSSFSheet sheet = wb.createSheet();        // 创建单元格样式        XSSFCellStyle style = wb.createCellStyle();        style.setFillForegroundColor(HSSFColor.WHITE.index);        ......        response.setContentType(&quot;application/octet-stream&quot;);        response.setHeader(&quot;Content-disposition&quot;, &quot;attachment;filename=createList.xls&quot;);//默认Excel名称        response.setHeader(&quot;Access-Control-Expose-Headers&quot;,&quot;*&quot;);        response.flushBuffer();        wb.write(response.getOutputStream());    &#125;catch (Exception e) &#123;        e.printStackTrace();    &#125;&#125;

